changeSet.sql:
ALTER TABLE ingestion_secret_restore_audit_outbox ADD CONSTRAINT ck_ingestion_secret_restore_audit_event_type CHECK (event_type IN ('ATTEMPT', 'RESULT')); ALTER TABLE ingestion_secret_restore_audit_outbox ADD CONSTRAINT ck_ingestion_secret_restore_audit_delivery CHECK (delivery_status IN ('PENDING', 'CLAIMED', 'RETRY', 'DELIVERED', 'DEAD')); ALTER TABLE ingestion_secret_restore_audit_outbox ADD CONSTRAINT ck_ingestion_secret_restore_audit_attempts CHECK (delivery_attempts >= 0); ALTER TABLE ingestion_secret_restore_audit_outbox ADD CONSTRAINT ck_ingestion_secret_restore_audit_identity CHECK (length(trim(tenant_id)) > 0 AND length(trim(actor)) > 0 AND length(trim(batch_id)) > 0 AND length(trim(classification)) > 0); ALTER TABLE ingestion_secret_restore_audit_outbox ADD CONSTRAINT ck_ingestion_secret_restore_audit_payload_hash CHECK (payload_hash ~ '^[0-9a-f]{64}$'); ALTER TABLE ingestion_secret_restore_audit_outbox ADD CONSTRAINT ck_ingestion_secret_restore_audit_claim CHECK ((delivery_status = 'CLAIMED' AND claimed_at IS NOT NULL) OR (delivery_status <> 'CLAIMED' AND claimed_at IS NULL)); ALTER TABLE ingestion_secret_restore_audit_outbox ADD CONSTRAINT ck_ingestion_secret_restore_audit_delivered CHECK ((delivery_status = 'DELIVERED' AND delivered_at IS NOT NULL) OR (delivery_status <> 'DELIVERED' AND delivered_at IS NULL));
CREATE OR REPLACE FUNCTION guard_ingestion_secret_restore_audit_update() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF ROW( NEW.id, NEW.event_id, NEW.tenant_id, NEW.actor, NEW.event_type, NEW.classification, NEW.batch_id, NEW.task_id, NEW.revision_id, NEW.config_checksum, NEW.outcome, NEW.error_code, NEW.payload_hash, NEW.payload_json, NEW.created_at ) IS DISTINCT FROM ROW( OLD.id, OLD.event_id, OLD.tenant_id, OLD.actor, OLD.event_type, OLD.classification, OLD.batch_id, OLD.task_id, OLD.revision_id, OLD.config_checksum, OLD.outcome, OLD.error_code, OLD.payload_hash, OLD.payload_json, OLD.created_at ) THEN RAISE EXCEPTION 'INGESTION_SECRET_RESTORE_AUDIT_EVIDENCE_IMMUTABLE'; END IF;
IF NOT ( ( OLD.delivery_status IN ('PENDING', 'RETRY', 'CLAIMED') AND NEW.delivery_status = 'CLAIMED' AND NEW.delivery_attempts = OLD.delivery_attempts + 1 AND NEW.claimed_at IS NOT NULL AND NEW.next_attempt_at IS NOT DISTINCT FROM OLD.next_attempt_at AND NEW.delivered_at IS NOT DISTINCT FROM OLD.delivered_at AND NEW.last_error IS NOT DISTINCT FROM OLD.last_error ) OR ( OLD.delivery_status = 'CLAIMED' AND NEW.delivery_status = 'DELIVERED' AND NEW.delivery_attempts = OLD.delivery_attempts AND NEW.claimed_at IS NULL AND NEW.delivered_at IS NOT NULL AND NEW.next_attempt_at IS NOT DISTINCT FROM OLD.next_attempt_at AND NEW.last_error IS NULL ) OR ( OLD.delivery_status = 'CLAIMED' AND NEW.delivery_status = 'RETRY' AND NEW.delivery_attempts = OLD.delivery_attempts AND NEW.claimed_at IS NULL AND NEW.delivered_at IS NOT DISTINCT FROM OLD.delivered_at AND NEW.next_attempt_at > CURRENT_TIMESTAMP AND length(trim(coalesce(NEW.last_error, ''))) > 0 ) OR ( OLD.delivery_status = 'CLAIMED' AND NEW.delivery_status = 'DEAD' AND NEW.delivery_attempts = OLD.delivery_attempts AND NEW.claimed_at IS NULL AND NEW.delivered_at IS NOT DISTINCT FROM OLD.delivered_at AND NEW.next_attempt_at IS NOT DISTINCT FROM OLD.next_attempt_at AND length(trim(coalesce(NEW.last_error, ''))) > 0 ) ) THEN RAISE EXCEPTION 'INGESTION_SECRET_RESTORE_AUDIT_DELIVERY_TRANSITION_INVALID'; END IF;
NEW.modified_at := CURRENT_TIMESTAMP; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION reject_ingestion_secret_restore_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP = 'TRUNCATE' THEN RAISE EXCEPTION 'INGESTION_SECRET_RESTORE_AUDIT_TRUNCATE_FORBIDDEN'; END IF; RAISE EXCEPTION 'INGESTION_SECRET_RESTORE_AUDIT_DELETE_FORBIDDEN'; END $$;
CREATE TRIGGER trg_ingestion_secret_restore_audit_update BEFORE UPDATE ON ingestion_secret_restore_audit_outbox FOR EACH ROW EXECUTE FUNCTION guard_ingestion_secret_restore_audit_update(); CREATE TRIGGER trg_ingestion_secret_restore_audit_delete BEFORE DELETE ON ingestion_secret_restore_audit_outbox FOR EACH ROW EXECUTE FUNCTION reject_ingestion_secret_restore_audit_mutation(); CREATE TRIGGER trg_ingestion_secret_restore_audit_truncate BEFORE TRUNCATE ON ingestion_secret_restore_audit_outbox FOR EACH STATEMENT EXECUTE FUNCTION reject_ingestion_secret_restore_audit_mutation()

rollback.sql:
DO $rollback$
BEGIN
    LOCK TABLE ingestion_secret_restore_audit_outbox IN ACCESS EXCLUSIVE MODE;
    IF EXISTS (SELECT 1 FROM ingestion_secret_restore_audit_outbox) THEN
        RAISE EXCEPTION 'ROLLBACK_BLOCKED_INGESTION_SECRET_RESTORE_AUDIT_EVIDENCE_EXISTS';
    END IF;
    EXECUTE 'DROP TABLE ingestion_secret_restore_audit_outbox';
    EXECUTE 'DROP FUNCTION guard_ingestion_secret_restore_audit_update()';
    EXECUTE 'DROP FUNCTION reject_ingestion_secret_restore_audit_mutation()';
END
$rollback$
